fees.jsonld:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    { "@type": "Question", "name": "How much does a skin check cost at Sunstate Family Practice?", "acceptedAnswer": { "@type": "Answer", "text": "A full skin check costs $109 to $170 depending on length and complexity. The indicative Medicare rebate is $45.05 to $87.10, leaving an out-of-pocket cost of $63.95 to $82.90. A spot check of 1 or 2 lesions costs $80 to $109, with $55.45 to $63.95 out of pocket." } },
    { "@type": "Question", "name": "How much does Total Body Mapping cost?", "acceptedAnswer": { "@type": "Answer", "text": "A Full Skin Check with Total Body Mapping costs $219 to $280. The indicative Medicare rebate of $45.05 to $87.10 applies to the skin check consultation, leaving $173.95 to $192.90 out of pocket. Private health fund rebates may apply for Total Body Mapping depending on your level of cover and health fund." } },
    { "@type": "Question", "name": "Does Sunstate Family Practice bulk bill?", "acceptedAnswer": { "@type": "Answer", "text": "Sunstate Family Practice is a private billing practice. Children 12 years and under are bulk billed for standard GP consultations between 8am and 5pm Monday to Friday. DVA Gold and White card holders are bulk billed for eligible conditions, and care plans, health assessments, home medication reviews, heart health assessments and immunisations are bulk billed." } },
    { "@type": "Question", "name": "Can I get my Medicare rebate on the day?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Payment is made at the time of your appointment and reception can process your Medicare claim through our Tyro facility, so your rebate is paid back straight away." } },
    { "@type": "Question", "name": "Do I need a referral for a skin check?", "acceptedAnswer": { "@type": "Answer", "text": "No. You do not need a referral to see a GP for a skin check. You can book online and choose a skin check appointment type, or call reception on (07) 3207 7744." } },
    { "@type": "Question", "name": "Is there an after-hours surcharge?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. A $20 surcharge applies to appointments before 8am and after 5pm Monday to Friday, and to all Saturday appointments." } },
    { "@type": "Question", "name": "What happens if my doctor finds a suspicious spot?", "acceptedAnswer": { "@type": "Answer", "text": "Your GP will discuss the next steps, which might include monitoring, a biopsy or removal of the lesion. Our doctors perform excisions in our on-site procedure room. Procedures attract additional costs, so please ask reception about the expected cost before proceeding." } }
  ]
}
